examples.template:
Column(
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
) {
    MonarchLink(text = {{back}}, onClick = { /* Back to the report list. */ })
    Row(
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        verticalAlignment = Alignment.Top,
    ) {
        Column(modifier = Modifier.weight(1f)) {
            MonarchText(text = {{title}}, style = MonarchTextStyle.Title)
            MonarchText(
                text = {{description}},
                color = MonarchTheme.colors.textMuted,
            )
        }
        MonarchDownloadReportButton(
            onDownload = { MonarchDownloadReportResult.Downloaded },
            formats = listOf(
                MonarchDownloadReportFormat(label = {{download.formats.0.label}}, id = {{download.formats.0.id}}),
                MonarchDownloadReportFormat(label = {{download.formats.1.label}}, id = {{download.formats.1.id}}),
            ),
            labels = MonarchDownloadReportButtonLabels(label = {{download.label}}),
        )
    }
    MonarchPeriodSelector(
        value = period,
        onValueChange = { period = it },
        presets = presets.map { it.second },
        today = {{periods.today|millis}},
        locale = Locale.forLanguageTag({{locale}}),
        timeZone = {{timeZone}},
    )
    Row(
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        MonarchText(text = {{scope}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        MonarchText(text = generated, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        MonarchBadge(text = {{badge.text}}, tone = {{badge.tone|tone}})
    }
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
        MonarchStatCard(label = {{kpis.0.label}}, value = {{kpis.0.value|double}}, modifier = Modifier.weight(1f), size = MonarchStatCardSize.Sm)
        MonarchStatCard(label = {{kpis.1.label}}, value = {{kpis.1.value|double}}, modifier = Modifier.weight(1f), size = MonarchStatCardSize.Sm)
        MonarchStatCard(label = {{kpis.2.label}}, value = {{kpis.2.value|double}}, modifier = Modifier.weight(1f), size = MonarchStatCardSize.Sm)
    }
    MonarchDataTable(
        caption = {{title}},
        rows = rows,
        columns = listOf(
            MonarchDataTableColumn<TeamRow>({{columns.0.label}}, id = {{columns.0.key}}, hideable = false) { it.team },
            MonarchDataTableColumn<TeamRow>({{columns.1.label}}, id = {{columns.1.key}}, numeric = true) { it.headcount.toString() },
            MonarchDataTableColumn<TeamRow>({{columns.2.label}}, id = {{columns.2.key}}, numeric = true) { it.joiners.toString() },
            MonarchDataTableColumn<TeamRow>({{columns.3.label}}, id = {{columns.3.key}}, numeric = true) { it.leavers.toString() },
            MonarchDataTableColumn<TeamRow>({{columns.4.label}}, id = {{columns.4.key}}) { if (it.remote) "Yes" else "No" },
        ),
        rowKey = { it.team },
        layout = MonarchDataTableLayout.Table,
    )
    MonarchText(text = {{notes.0}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
}

examples.setupTemplate:
data class TeamRow(val team: String, val headcount: Int, val joiners: Int, val leavers: Int, val remote: Boolean)
val rows = listOf(
    TeamRow({{rows.0.team}}, {{rows.0.headcount}}, {{rows.0.joiners}}, {{rows.0.leavers}}, {{rows.0.remote}}),
    TeamRow({{rows.1.team}}, {{rows.1.headcount}}, {{rows.1.joiners}}, {{rows.1.leavers}}, {{rows.1.remote}}),
    TeamRow({{rows.2.team}}, {{rows.2.headcount}}, {{rows.2.joiners}}, {{rows.2.leavers}}, {{rows.2.remote}}),
)
// The web preset values, as Monarch presets.
val presets = listOf(
    {{periods.presets.0}} to MonarchPeriodPreset.Last30Days,
    {{periods.presets.1}} to MonarchPeriodPreset.ThisQuarter,
    {{periods.presets.2}} to MonarchPeriodPreset.ThisYear,
    {{periods.presets.3}} to MonarchPeriodPreset.Custom,
)
var period by remember { mutableStateOf(MonarchPeriodValue(presets.first().second)) }
val generated = remember {
    "Generated " + DateFormat.getDateTimeInstance(DateFormat.MEDIUM, DateFormat.SHORT, Locale.forLanguageTag({{locale}}))
        .apply { timeZone = TimeZone.getTimeZone({{timeZone}}) }
        .format(Date({{generatedAt|millis}}))
}

examples.setup:
data class TeamRow(val team: String, val headcount: Int, val joiners: Int, val leavers: Int, val remote: Boolean)
val rows = listOf(
    TeamRow("Design", 14, 2, 0, true),
    TeamRow("Engineering", 41, 5, 1, true),
    TeamRow("Support", 18, 1, 2, false),
)
// The web preset values, as Monarch presets.
val presets = listOf(
    "30d" to MonarchPeriodPreset.Last30Days,
    "this-quarter" to MonarchPeriodPreset.ThisQuarter,
    "this-year" to MonarchPeriodPreset.ThisYear,
    "custom" to MonarchPeriodPreset.Custom,
)
var period by remember { mutableStateOf(MonarchPeriodValue(presets.first().second)) }
val generated = remember {
    "Generated " + DateFormat.getDateTimeInstance(DateFormat.MEDIUM, DateFormat.SHORT, Locale.forLanguageTag("en-GB"))
        .apply { timeZone = TimeZone.getTimeZone("UTC") }
        .format(Date(1_794_045_600_000L))
}

examples.code:
Column(
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
) {
    MonarchLink(text = "All reports", onClick = { /* Back to the report list. */ })
    Row(
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        verticalAlignment = Alignment.Top,
    ) {
        Column(modifier = Modifier.weight(1f)) {
            MonarchText(text = "Headcount by team", style = MonarchTextStyle.Title)
            MonarchText(
                text = "People on the payroll at the end of the period.",
                color = MonarchTheme.colors.textMuted,
            )
        }
        MonarchDownloadReportButton(
            onDownload = { MonarchDownloadReportResult.Downloaded },
            formats = listOf(
                MonarchDownloadReportFormat(label = "CSV", id = "csv"),
                MonarchDownloadReportFormat(label = "Excel", id = "xlsx"),
            ),
            labels = MonarchDownloadReportButtonLabels(label = "Download"),
        )
    }
    MonarchPeriodSelector(
        value = period,
        onValueChange = { period = it },
        presets = presets.map { it.second },
        today = 1_794_009_600_000L,
        locale = Locale.forLanguageTag("en-GB"),
        timeZone = "UTC",
    )
    Row(
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        MonarchText(text = "All locations", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        MonarchText(text = generated, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        MonarchBadge(text = "Contains pay figures", tone = MonarchTone.Warning)
    }
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
        MonarchStatCard(label = "Headcount", value = 73.0, modifier = Modifier.weight(1f), size = MonarchStatCardSize.Sm)
        MonarchStatCard(label = "Joined", value = 8.0, modifier = Modifier.weight(1f), size = MonarchStatCardSize.Sm)
        MonarchStatCard(label = "Left", value = 3.0, modifier = Modifier.weight(1f), size = MonarchStatCardSize.Sm)
    }
    MonarchDataTable(
        caption = "Headcount by team",
        rows = rows,
        columns = listOf(
            MonarchDataTableColumn<TeamRow>("Team", id = "team", hideable = false) { it.team },
            MonarchDataTableColumn<TeamRow>("Headcount", id = "headcount", numeric = true) { it.headcount.toString() },
            MonarchDataTableColumn<TeamRow>("Joined", id = "joiners", numeric = true) { it.joiners.toString() },
            MonarchDataTableColumn<TeamRow>("Left", id = "leavers", numeric = true) { it.leavers.toString() },
            MonarchDataTableColumn<TeamRow>("Remote", id = "remote") { if (it.remote) "Yes" else "No" },
        ),
        rowKey = { it.team },
        layout = MonarchDataTableLayout.Table,
    )
    MonarchText(text = "Contractors are excluded.", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
}

Column(Modifier.fillMaxSize()) {
    TopAppBar(title = { Text("Payroll summary") })
    if (failed) {
        MonarchErrorState(
            title = "This report could not be run.",
            onRetry = { failed = false /* Run the report again. */ },
        )
    } else {
        // A first run: placeholders, read as one busy element.
        MonarchLoadingState(label = "Loading report", variant = MonarchLoadingStateVariant.Rows)
    }
}
